<script setup lang="ts">
import { computed, ref, watch, onBeforeUnmount, nextTick } from 'vue'
import { useLab } from './store'
import { DATASET, kindNames, metrics, segments, signature, strategyNames } from './domain'
import { phases, knowledge } from './scenario'
import SceneView from './components/SceneView.vue'
import StepPanel from './components/StepPanel.vue'
import TrendChart from './components/TrendChart.vue'
const lab = useLab(), fileInput = ref<HTMLInputElement>(), compareIds = ref<number[]>([]), showLegacy = ref(false)
const review = ref({ reviewer: '', explanation: 0, limits: 0, feedback: '', trialIds: [] as number[] })
const compared = computed(() => lab.saved.trials.filter(t => !compareIds.value.length || compareIds.value.includes(t.id)))
const conclusionLabels = { mapping: '关联与错配：错误如何影响读数，如何证明修复有效？', period: '发布周期：条数、尖峰可见性和告警时刻分别说明什么？', strategy: '规则策略：误触发、延迟、切换和恢复之间如何权衡？', transfer: '独立迁移：新台账出现什么问题，你依据什么定位并修复？', limits: '结论边界：模拟数据、前端成绩和当前方案有哪些限制？' }
const formatDate = (text: string) => new Date(text).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', hour12: false })
const currentReading = computed(() => lab.reading(lab.selected))
watch(() => lab.page, p => { if (p !== 'lab') lab.pause() })
onBeforeUnmount(lab.pause)
function download(text: string, name: string, mime = 'application/json') { const url = URL.createObjectURL(new Blob([text], { type: mime+';charset=utf-8' })); const a = document.createElement('a'); a.href = url; a.download = name; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000) }
async function importFile(e: Event) { const f = (e.target as HTMLInputElement).files?.[0]; if (!f) return; try { if (f.size > 20_000_000) throw new Error('文件不能超过20 MB。'); const text = await f.text(); lab.importArchive(text); showLegacy.value = JSON.parse(text).version === 1 } catch (err) { lab.lastMessage = (err as Error).message }; (e.target as HTMLInputElement).value = '' }
async function printReport() { compareIds.value = []; await nextTick(); const details = Array.from(document.querySelectorAll<HTMLDetailsElement>('.core-report details')); const open = details.map(d => d.open); details.forEach(d => d.open = true); window.print(); details.forEach((d,i) => d.open = open[i]!) }
function exportReport() {
 const report = { title: '泵电流监测单元实验报告', dataset: DATASET, exportedAt: new Date().toISOString(), currentConfigAccepted: lab.currentAccepted, automatic: { score: lab.autoScore, max: 70, results: lab.results }, teacher: { score: lab.teacherScore, max: 30, current: lab.reviewValid, review: lab.saved.review }, submitted: lab.submitted, conclusions: lab.saved.conclusions, archive: lab.saved }
 download(JSON.stringify(report,null,2),'泵电流实验-报告及证据.json')
}
</script>
<template>
<div class="core-shell">
  <header class="core-header"><button class="core-brand" @click="lab.page='overview'">◇ 孪生工坊 <span>核心实验 v2.0</span></button><nav aria-label="主导航"><button :class="{active:lab.page==='overview'}" @click="lab.page='overview'">课程总览</button><button :class="{active:lab.page==='lab'}" @click="lab.page='lab'">实验工作台</button><button :class="{active:lab.page==='report'}" @click="lab.page='report'">实验报告</button></nav><span class="core-local">本地教学实例</span></header>
  <main v-if="lab.page==='overview'" class="core-overview">
    <section class="core-hero"><div><div class="core-eyebrow">数字孪生技术与应用 · 核心实验01</div><h1>让每一次配置，<br>经得起实验验证。</h1><h2>泵电流监测单元的数字孪生构建与告警验证</h2><p>把正确数据关联到三维设备，用同一输入比较发布周期和告警策略。先预测、动手试验，再用证据解释结果。</p><div class="core-chips"><span>2学时 · 90分钟</span><span>配置与验证</span><span>自动70 + 教师30分</span></div><button class="btn primary" @click="lab.page='lab'">{{ lab.saved.trials.length ? '继续实验' : '进入核心实验' }} →</button></div><SceneView hero /></section>
    <section class="core-section"><h2>本例聚焦四个知识点</h2><div class="core-knowledge"><article v-for="k in knowledge" :key="k.title" class="core-card"><h3>{{ k.title }}</h3><p>{{ k.content }}</p></article></div></section>
    <section class="core-section"><h2>90分钟，做出可检查的实验结果</h2><div class="core-phase-grid"><button v-for="(p,i) in phases" :key="p.title" class="core-card core-phase-card" @click="lab.setPhase(i);lab.page='lab'"><span class="core-eyebrow">0{{ i+1 }} / {{ p.minutes }}分钟</span><h3>{{ p.title }}</h3><p>{{ p.question }}</p><strong>{{ p.output }}</strong></button></div></section>
    <section class="core-card core-boundary"><h2>建设进度与使用边界</h2><p>本例已实现对象关联、固定输入回放、周期与规则对照、事件处置和证据报告。完整课程仍为8学时、28步规划；数据治理、缓存补传、状态机编辑和AI专项评测待建设。</p><p>自建三维模型、教学模拟数据，不连接生产设备。本地提示不是大模型。浏览器记录不具备服务端身份认证或防作弊能力。</p><div class="core-actions"><a href="/实验指导.md" target="_blank" rel="noopener">实验指导</a><a href="/教师评分表.md" target="_blank" rel="noopener">教师评分表</a><a href="/试教记录表.md" target="_blank" rel="noopener">五人试教记录表</a></div></section>
  </main>
  <main v-else-if="lab.page==='lab'" class="core-workbench">
    <div class="core-lab-heading"><div><div class="core-eyebrow">先预测 → 配置 → 同输入回放 → 记录 → 解释</div><h1>泵电流监测单元</h1></div><span class="core-score">实验证据 {{ lab.autoScore }}/70 · 教师 {{ lab.reviewValid ? lab.teacherScore+'/30' : '待复核' }}</span></div>
    <nav class="core-phases" aria-label="实验环节"><button v-for="(p,i) in phases" :key="p.title" :class="{active:lab.saved.phase===i}" @click="lab.setPhase(i)"><b>0{{ i+1 }}</b>{{ p.title }}<small>{{ p.minutes }}分钟</small></button></nav>
    <div class="core-lab-grid"><div class="core-lab-main">
      <section class="core-card core-replay"><div class="core-replay-title"><h2>固定输入回放 <small>{{ lab.active ? '#'+lab.active.id+' · '+kindNames[lab.active.kind] : '尚未开始' }}</small></h2><strong>T+{{ String(lab.active?.tick ?? 0).padStart(2,'0') }} / 40s</strong></div><div class="core-actions"><button class="btn primary" @click="lab.startTrial">新建试验并回放</button><button class="btn" @click="lab.running?lab.pause():lab.play()" :disabled="!lab.active || lab.active.complete || !lab.currentMatches">{{ lab.running?'暂停':'继续' }}</button><button class="btn" @click="lab.pause();lab.step()" :disabled="!lab.active || lab.active.complete || !lab.currentMatches">前进1秒</button><button class="btn" @click="lab.finish" :disabled="!lab.active || lab.active.complete || !lab.currentMatches">回放至终点</button></div><p class="core-small">每轮重置到1秒，依次计算全部40个源样本。快捷回放也逐样本计算，不跳过输入。{{ DATASET }}</p><p v-if="lab.active && !lab.currentMatches" class="core-warning">当前配置与查看的试验不同。历史结果保留；请新建试验验证新配置。</p><p class="core-status">当前配置：{{ lab.currentAccepted ? '已完成回放与观察验收' : '待回放 / 待记录观察' }}</p></section>
      <section class="core-scene-card"><SceneView /><div class="core-assets"><button v-for="a in lab.saved.config.assets" :key="a.id" :class="{active:lab.selected===a.id}" @click="lab.choose(a.id,'tree')">{{ a.name }}<small>{{ a.code }}</small></button></div></section>
      <section class="core-card"><div class="core-replay-title"><h2>资产数据与事件时间</h2><strong>{{ currentReading ? currentReading.value+' '+currentReading.unit : '—' }}</strong></div><p :class="currentReading && !currentReading.valid?'core-warning':'core-small'">{{ currentReading?.quality ?? '等待有效发布数据' }} · 资产读数按当前配置预览；下图保留试验的锁定配置。</p><TrendChart /></section>
      <section class="core-card"><h2>固定输入与教学标注</h2><div class="core-segments"><div v-for="s in segments" :key="s.start"><strong>{{ s.start }}—{{ s.end }}s</strong><span>{{ s.name }}</span><small>{{ s.truth?'教学事件持续中':'非目标事件' }}</small></div></div><p class="core-small">11—34秒标注为同一教学事件。误触发按该段之外的触发计数；检测延迟从第11秒起算。标注用于技术验证，不是实际设备故障判断。</p></section>
      <section class="core-card"><h2>检测输出与人工事件处置</h2><p class="core-small">检测器继续处理每个样本；未确认或待关闭事件不会屏蔽下一次越限。</p><p>检测信号：{{ lab.active?.detector.active ? '越限中' : '未激活' }} · {{ lab.active?.detections.map(e=>e.tick+'s '+(e.type==='trigger'?'触发':'恢复')).join('；') || '尚无事件' }}</p><div class="table-scroll"><table><thead><tr><th>事件</th><th>触发</th><th>恢复</th><th>确认</th><th>关闭</th><th>操作</th></tr></thead><tbody><tr v-for="e in lab.active?.incidents" :key="e.id"><td>#{{ e.id }}</td><td>{{ e.triggeredAt }}s</td><td>{{ e.recoveredAt === null?'未恢复':e.recoveredAt+'s' }}</td><td>{{ e.acknowledgedAt === null?'待确认':e.acknowledgedAt+'s' }}</td><td>{{ e.closedAt === null?'待关闭':e.closedAt+'s' }}</td><td><button class="core-link" :disabled="e.acknowledgedAt!==null" @click="lab.acknowledge(e.id)">确认事件{{ e.id }}</button><button class="core-link" :disabled="e.closedAt!==null" @click="lab.closeIncident(e.id)">复核关闭{{ e.id }}</button></td></tr></tbody></table></div></section>
      <section class="core-card"><h2>实验证据进度</h2><div v-for="r in lab.results" :key="r.id" class="core-achievement"><div><strong>{{ r.title }}</strong><p>{{ r.detail }}</p><small>证据：{{ r.trialIds.map(id=>'#'+id).join('、') || '尚未满足' }}</small></div><b>{{ r.earned }}/{{ r.max }}</b></div><button class="btn" @click="lab.page='report'">查看对照表与填写结论 →</button></section>
    </div><StepPanel /></div>
  </main>
  <main v-else class="core-report">
    <div class="core-lab-heading"><div><div class="core-eyebrow">从配置快照到可复现证据</div><h1>实验报告</h1><p>泵电流监测单元的数字孪生构建与告警验证</p></div><div class="core-actions no-print"><button class="btn" @click="fileInput?.click()">导入备份</button><button class="btn" @click="download(lab.exportJson(),'泵电流实验-v2备份.json')">导出备份</button><button class="btn" @click="exportReport">导出报告与证据</button><button class="btn primary" @click="printReport">打印报告</button></div></div>
    <section class="core-card"><div class="core-report-summary"><strong>{{ lab.totalScore }}<small>/100</small></strong><div><p>自动实验证据 {{ lab.autoScore }}/70 · 教师论证 {{ lab.reviewValid ? lab.teacherScore+'/30' : '待复核 / 30' }}</p><p>报告：{{ lab.submitted?'已提交':'未提交或证据已变化' }} · 当前配置：{{ lab.currentAccepted?'已验收':'待复验' }}</p><p class="core-small">{{ DATASET }} · 全部试验均使用1—40秒输入。历史达成保留，当前方案须单独验收；文字内容不自动得论证分。</p></div></div><p class="core-small">本地教师录分仅作试教记录，不构成身份认证或可信服务端成绩。</p></section>
    <section class="core-card"><h2>同输入实验对照</h2><p>选择试验并排比较；配置差异须与研究变量一致。恢复时刻仅统计35秒后恢复。</p><div class="core-compare-choices no-print"><label v-for="t in lab.saved.trials" :key="t.id"><input v-model="compareIds" type="checkbox" :value="t.id" />#{{ t.id }} {{ kindNames[t.kind] }}</label><button class="core-link" @click="compareIds=[]">显示全部</button></div><div class="table-scroll"><table><thead><tr><th>试验 / 类型</th><th>配置与完整性</th><th>发布数 / 尖峰可见</th><th>误触发 / 检测延迟</th><th>切换 / 恢复时刻</th><th>源触发 / 恢复</th></tr></thead><tbody><tr v-for="t in compared" :key="t.id"><td>#{{ t.id }} {{ kindNames[t.kind] }}</td><td>{{ strategyNames[t.config.strategy] }} · {{ t.config.period }}s<br>{{ t.complete?'完整40秒':t.tick+'秒 · 未完成' }}<br>{{ signature(t.config)===signature(lab.saved.config)?'与当前一致':'历史配置' }}</td><td>{{ metrics(t).published }} / {{ metrics(t).visibleSpike?'可见':'未见' }}</td><td>{{ metrics(t).falseTriggers }} / {{ metrics(t).delay===null?'未检出':metrics(t).delay+'s' }}</td><td>{{ metrics(t).switches }} / {{ metrics(t).recoveryAt===null?'—':metrics(t).recoveryAt+'s' }}</td><td>{{ t.detections.map(e=>e.tick+'s'+(e.type==='trigger'?'↑':'↓')).join(' ') || '无' }}</td></tr></tbody></table></div><p v-if="!lab.saved.trials.length">暂无试验记录，配置正确本身不计实验分。</p></section>
    <section class="core-card"><h2>评分依据</h2><div v-for="r in lab.results" :key="r.id" class="core-achievement"><div><strong>{{ r.title }}</strong><p>{{ r.detail }}</p><small>试验 {{ r.trialIds.join('、') || '待完成' }}</small></div><b>{{ r.earned }}/{{ r.max }}</b></div></section>
    <section class="core-card"><h2>实验结论与适用边界</h2><p>引用试验编号和实测数字，说明预测是否成立、哪项证据支持结论。字数仅用于提交完整性，不自动计分。</p><label v-for="(label,key) in conclusionLabels" :key="key" class="field"><span>{{ label }}</span><textarea v-model="lab.saved.conclusions[key]" :aria-label="label" rows="3" maxlength="20000" class="no-print" /><p class="print-only core-conclusion">{{ lab.saved.conclusions[key] || '尚未填写' }}</p></label><button class="btn primary no-print" @click="lab.submit">提交报告等待教师复核</button><p v-if="lab.saved.review && !lab.reviewValid" class="core-warning">证据或结论已变更，旧教师评价保留供追溯，但不计入当前总分。请重新提交并复核。</p></section>
    <section class="core-card"><h2>逐次试验证据</h2><details v-for="t in lab.saved.trials" :key="t.id" class="core-trial-detail"><summary>#{{ t.id }} {{ kindNames[t.kind] }} · {{ strategyNames[t.config.strategy] }} · {{ t.tick }}/40秒</summary><div><p><b>数据版本：</b>{{ t.dataset }} / {{ formatDate(t.startedAt) }} / {{ t.complete?'完整':'未完成' }}</p><p><b>运行前预测：</b>{{ t.prediction }}</p><p v-for="(edit,i) in t.predictionHistory" :key="i" class="core-small">预测修订{{ i+1 }} · {{ formatDate(edit.at) }} · {{ edit.text }}</p><pre>{{ JSON.stringify(t.config,null,2) }}</pre><p v-for="(o,i) in t.observations" :key="i">观察{{ i+1 }}：源{{ o.tick }}s（{{ o.sourceValue ?? '—' }}），发布{{ o.displayTick ?? o.tick }}s · {{ o.model }}模型 → {{ o.code || '未绑定' }} → {{ o.field || '无字段' }} → {{ o.value ?? '—' }} {{ o.unit }} · {{ o.quality }}<br>{{ o.note }}</p><p v-if="!t.observations.length">尚未保存观察，此试验不计实验证据分。</p><p>检测：{{ t.detections.map(e=>e.tick+'s '+e.type).join('；') || '无' }}</p><p v-for="e in t.incidents" :key="e.id">事件{{ e.id }}：触发{{ e.triggeredAt }}s；确认{{ e.acknowledgedAt ?? '—' }}；恢复{{ e.recoveredAt ?? '—' }}；关闭{{ e.closedAt ?? '—' }}</p><div class="core-actions no-print"><button class="btn" @click="lab.selectTrial(t.id);lab.page='lab'">查看此试验</button><button class="btn" @click="lab.repeatTrial(t.id);lab.page='lab'">复制配置并重放</button></div></div></details></section>
    <section class="core-card"><h2>教师评价记录</h2><p>教师依据实际试验和结论评分，需人工复核。本地页面没有教师身份隔离。</p><div v-if="lab.saved.review"><p>{{ lab.saved.review.reviewer }} · {{ formatDate(lab.saved.review.at) }} · {{ lab.reviewValid?'当前有效':'历史评价' }}</p><p>解释与证据 {{ lab.saved.review.explanation }}/20；边界 {{ lab.saved.review.limits }}/10；引用试验 {{ lab.saved.review.trialIds.join('、') }}</p><p>{{ lab.saved.review.feedback }}</p></div><details class="no-print"><summary>录入教师复核（需先提交报告）</summary><label class="field"><span>复核教师</span><input v-model="review.reviewer" aria-label="复核教师" /></label><div class="core-two"><label class="field"><span>解释与证据一致 / 20</span><input v-model.number="review.explanation" aria-label="解释与证据评分" type="number" min="0" max="20" /></label><label class="field"><span>结论边界 / 10</span><input v-model.number="review.limits" aria-label="结论边界评分" type="number" min="0" max="10" /></label></div><p>引用的完整试验：</p><div class="core-compare-choices"><label v-for="t in lab.saved.trials.filter(t=>t.complete)" :key="t.id"><input v-model="review.trialIds" type="checkbox" :value="t.id" />#{{ t.id }}</label></div><label class="field"><span>依据与改进反馈</span><textarea v-model="review.feedback" aria-label="教师反馈" rows="3" maxlength="20000" /></label><button class="btn" @click="lab.review(review)">保存教师复核记录</button></details></section>
    <section class="core-card"><h2>配置变更与复测记录</h2><details v-for="(entry,i) in lab.saved.logs" :key="i"><summary>{{ formatDate(entry.at) }} · {{ entry.text }}</summary><div v-if="entry.before"><h4>变更前</h4><pre>{{ JSON.stringify(entry.before,null,2) }}</pre><h4>变更后</h4><pre>{{ JSON.stringify(entry.after,null,2) }}</pre></div></details></section>
  </main>
  <footer class="core-footer"><span>{{ lab.persistenceError || '本地自动保存 · v1存档保留只读 · 不连接生产设备' }}</span><button v-if="lab.legacy" class="core-link" @click="showLegacy=true">查看v1只读存档</button><button class="core-link" @click="fileInput?.click()">导入v1/v2备份</button><button class="core-link" @click="download(lab.exportJson(),'泵电流实验-v2备份.json')">导出v2备份</button></footer>
  <input ref="fileInput" type="file" accept=".json,application/json" class="hidden" @change="importFile" />
  <div v-if="lab.lastMessage" class="core-toast" role="status"><span>{{ lab.lastMessage }}</span><button aria-label="关闭通知" @click="lab.lastMessage=''">×</button></div>
  <div v-if="showLegacy && lab.legacy" class="modal-backdrop" @click.self="showLegacy=false"><section class="modal core-legacy" role="dialog" aria-modal="true" aria-label="v1只读存档"><h2>v1只读存档</h2><p>旧配置和成绩不转为v2得分，原始v1浏览器存储保持保留。</p><p v-for="(a,i) in lab.legacy.assets" :key="i">{{ a.name }} · {{ a.code }}</p><p>{{ lab.legacy.reflection }}</p><div class="core-legacy-events"><p v-for="(e,i) in lab.legacy.events" :key="i">{{ e.tick }}s · {{ e.text }}</p></div><div class="core-actions"><button class="btn" @click="download(lab.legacy!.raw,'数字孪生实验-v1原始备份.json')">导出v1原始存档</button><button class="btn primary" @click="showLegacy=false">关闭只读存档</button></div></section></div>
</div>
</template>


